mapper.select:
select CALENDAR_ID id, CALENDAR_NAME text from MST_CALENDAR_INFO
and (CALENDAR_ID like concat(concat('%',#{search}),'%') or CALENDAR_NAME like concat(concat('%',#{search}),'%'))
and IS_TRADE_CALENDAR = #{isTradeCalendar}

select COUNTER_ID id, COUNTER_NAME text from MST_COUNTER_PARTY
and (COUNTER_ID like concat(concat('%',#{search}),'%') or COUNTER_NAME like concat(concat('%',#{search}),'%'))
and COUNTER_TYPE = #{counterType}

select CUSTOMER_ID id, CUSTOMER_NAME text from MST_CUSTOMER_INFO
and (CUSTOMER_ID like concat(concat('%',#{search}),'%') or CUSTOMER_NAME like concat(concat('%',#{search}),'%'))
and CUSTOMER_ID = #{initValue}
and IS_ISSUER = #{isIssuer}

SELECT
FINPROD_MARKET_ID code,
case FINPROD_TYPE2 when #{FINPROD_TYPE_TG_ZQ}
then FINPROD_ABBR
when #{FINPROD_TYPE_TG_JJ}
then FINPROD_ABBR
ELSE FINPROD_NAME
end name,
case FINPROD_TYPE2 when #{FINPROD_TYPE_TG_ZQ}
then  FINPROD_ABBR
when #{FINPROD_TYPE_TG_JJ}
then FINPROD_ABBR
ELSE FINPROD_NAME end shortName,
FINPROD_MARKET_ID hidCode
FROM FIN_PRODUCT


		and (FINPROD_MARKET_ID like concat(concat('%',#{search}),'%')
    			or FINPROD_ABBR like concat(concat('%',#{search}),'%'))



			AND FINPROD_TYPE2 in 

				#{item}



		AND P_FINPROD_ID IS NULL


	  	and PROFIT_TYPE = #{profitType,jdbcType=VARCHAR}

SELECT T1.COUPON_SPECIES, T3.INT_TYPE FROM FIN_PRODUCT T1 LEFT JOIN FIN_CASH_INFO T2 ON T2.FINPROD_ID = T1.FINPROD_ID
AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
LEFT JOIN FIN_RATE_INFO T3 ON T3.CASH_ID = T2.CASH_ID AND T3.EFF_DATE = T1.VDATE
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

SELECT
count( * )
FROM
FIN_PRODUCT


		and FINPROD_MARKET_ID = #{finprodMarketId}


		and FINPROD_NAME = #{finprodName}

	AND FINPROD_TYPE2=#{F28}

SELECT
	INPUT_VALUE_1 inputValue1,
	INPUT_VALUE_2 inputValue2,
	INPUT_VALUE_3 inputValue3,
	INPUT_VALUE_4 inputValue4,
	INPUT_VALUE_5 inputValue5
FROM
    FIN_PRODUCT_TYPE_CONFIG
WHERE CONFIG_TYPE = #{configType}

    AND INPUT_VALUE_1 = #{inputValue1}


    AND OUTPUT_VALUE_1 = #{inputValue2}


    AND OUTPUT_VALUE_2 = #{inputValue3}


    AND OUTPUT_VALUE_3 = #{inputValue4}


    AND OUTPUT_VALUE_4 = #{inputValue5}

	select TYPE_6, TYPE_7, TYPE_8, IS_CREATE_PORTFOLIO
             from ASSET_TYPE_CONFIG


             		 and TYPE_6 = #{type_6}


             		 and TYPE_7 = #{type_7}


             		 and TYPE_8 = #{type_8}

select fin_product.FINPROD_ID FINPROD_IDZ, FIN_PRODUCT_ADD.FINPROD_ID FINPROD_IDFS, fin_product.FINPROD_ID , FIN_PRODUCT_TYPE.TYPE_3 , FIN_PRODUCT_TYPE.BRANCH BRANCHBD , fin_product.FINPROD_TYPE , fin_product.FINPROD_TYPE2 , fin_product.FINPROD_ABBR , fin_product.FINPROD_NAME , fin_product.PROFIT_TYPE , null as BRANCH_TYPE, null as CHL_AGRT_ID, null as PRIN, fin_product.CCY , fin_product.VDATE , fin_product.MDATE , fin_product.TERM_DAYS , null as INT_TYPE, null as INT_RATE, null as INT_RATE_ID, null as BASIS, null as M_PRIN_AMT, null as M_INT_AMT, null as M_TRADE_AMT, fin_product.CAPI_INCOME_FEATURE , fin_product.O_FINPROD_ID , fin_product.TRADE_MARKET , fin_product.CALENDAR_ID , FIN_PRODUCT_ADD.TERM_TYPE , null as COUNTER_ID, null as M_UNIT_CPRICE, null as M_UNIT_INT, null as M_UNIT_FPRICE, null as M_YIELD, null as M_DELIVERY_TYPE, null as VPAY_DATE, null as MPAY_DATE, fin_product.CONTRACT_NO , null as ACT_CAP_DAYS, null as IRS_TYPE, null as EXC_PS, null as CUR_PAIR, null as EXC_FXS_TERM_TYPE, null as USD_AMT, null as DIF_SETTLE_REF_RATE, null as CONFLICT_SOLVE_WAY, null as PERIOD_ID, null as IS_RUSH_BACK, null as CONTRACT_NAME, fin_product.REGIST_ORG , null as REGIST_ORGFS, null as PLEDGE_SEC_NUMFS, fin_product.CREATE_USER , fin_product.CREATE_DEPT , fin_product.CREATE_TIME , fin_product.UPDATE_USER , fin_product.UPDATE_TIME , null as EXCHANGE_PLEDGEFS, null as SUPPLY_CLAUSEFS, null as IS_ACCR_PENALTY_INTFS, null as PENALTY_BASE_TYPEFS, null as OPT_FEE_PAY_TYPEFS, null as OPT_FEE_AMTFS, null as OPT_FEE_RATEFS, fin_product.COUPON_SPECIES , fin_product.CHL_FINPROD_ID , fin_product.FINPROD_MARKET_ID , fin_product.ISSUE_ID , fin_product.ISSUE_PRICE , fin_product.ISSUE_AMT , fin_product.BLN_AREA , fin_product.ISSUE_TYPE , fin_product.OPERATION_TYPE , fin_product.ENTRUST_TYPE , fin_product.ENTRUSTER , fin_product.TRUSTEE_ID , fin_product.ISSUER , fin_product.MANAGER , fin_product.FINANCIER , fin_product.IDATE , fin_product.ACTMDATE , fin_product.LIQUIDATION_DATE , fin_product.IS_CHL , fin_product.IS_SUS , fin_product.SUSTAINABLE_REMARK , fin_product.IS_RIGHT , fin_product.P_FINPROD_ID , fin_product.EXE_DATE , fin_product.REMARK , fin_product.IS_FIN_ORG , fin_product.SPONSOR , fin_product.INVEST_ADVISER , fin_product.LIQUIDATION_YESNO , FIN_PRODUCT_ADD.SALE_DEPARTMENT , FIN_PRODUCT_ADD.SALE_LAYER , FIN_PRODUCT_ADD.SALE_PERIOD , FIN_PRODUCT_ADD.PUR_SPEED , FIN_PRODUCT_ADD.RED_SPEED , FIN_PRODUCT_ADD.IS_SEC_BOND , FIN_PRODUCT_ADD.WIND_ID windId, FIN_PRODUCT_ADD.IS_AUTO_UPDATE , FIN_PRODUCT_ADD.PORTFOLIO_ID , FIN_PRODUCT_ADD.PROD_REGIST_CODE , FIN_PRODUCT_ADD.IS_CYCLE , FIN_PRODUCT_ADD.IS_LAY , FIN_PRODUCT_ADD.LAY_TYPE , FIN_PRODUCT_ADD.INVEST_NATURE , FIN_PRODUCT_ADD.PROFIT_FLAG , FIN_PRODUCT_ADD.SALE_MODE , FIN_PRODUCT_ADD.CHB_ID , FIN_PRODUCT_ADD.TMPL_ID , FIN_PRODUCT_ADD.CLOSE_DAYS , FIN_PRODUCT_ADD.ISSUE_STATUS , FIN_PRODUCT_ADD.ISSUE_STATUS_REMARK , FIN_PRODUCT_ADD.IS_COMPOUND_INT , FIN_PRODUCT_ADD.FACE_VALUE , FIN_PRODUCT_ADD.PAY_TYPE , FIN_PRODUCT_ADD.IS_RECONCILIATION , FIN_PRODUCT_ADD.IS_CASH_MANAGE , FIN_PRODUCT_ADD.RISK_LEVEL , FIN_PRODUCT_ADD.DEAL_MODE , FIN_PRODUCT_ADD.IS_EXCLUSIVE , FIN_PRODUCT_ADD.BID_DATE , FIN_PRODUCT_ADD.BOARD , FIN_PRODUCT_ADD.SH_OR_ZH , FIN_PRODUCT_ADD.IS_MARGIN_FINPROD , FIN_PRODUCT_ADD.CITY_BOND_LEV , FIN_PRODUCT_ADD.IS_CITY_BOND , FIN_PRODUCT_ADD.INVESTMENT_CYCLE , FIN_PRODUCT_ADD.PROD_MANAGER , FIN_PRODUCT_ADD.COLLECT_TYPE , FIN_PRODUCT_ADD.REGULATORY_RATING , FIN_PRODUCT_ADD.PRD_DESIGN_ID , FIN_PRODUCT_ADD.ADDITION , FIN_PRODUCT_ADD.IS_PLEDGE_REP , FIN_PRODUCT_ADD.TOFF_STRDATE , FIN_PRODUCT_ADD.TOFF_ENDDATE , FIN_PRODUCT_ADD.TRM_FUND_ABBR , FIN_PRODUCT_ADD.TRM_FUND_TYPE , FIN_PRODUCT_ADD.GRA_FUND_TYPE , FIN_PRODUCT_ADD.PUR_RED_ID , FIN_PRODUCT_ADD.PUR_RED_ABBR , FIN_PRODUCT_ADD.PUR_START_LOW , FIN_PRODUCT_ADD.RED_START_LOW , FIN_PRODUCT_ADD.ETF_TYPE , FIN_PRODUCT_ADD.ETF_MIN_PRUNIT , FIN_PRODUCT_ADD.IS_RECEIPT , /*FIN_PRODUCT_ADD.ACTUAL_CREDIT_PROVID ,*/ FIN_PRODUCT_ADD.NO_FIXED_TERM, FIN_PRODUCT_TYPE.TYPE_1 , FIN_PRODUCT_TYPE.TYPE_2 , FIN_PRODUCT_TYPE.TYPE_4 , FIN_PRODUCT_TYPE.TYPE_5 , FIN_PRODUCT_TYPE.TYPE_6 , FIN_PRODUCT_TYPE.TYPE_7 , FIN_PRODUCT_TYPE.TYPE_8 , FIN_PRODUCT_TYPE.TYPE_9 , FIN_PRODUCT_TYPE.TYPE_10 , FIN_PRODUCT_TYPE.TYPE_11 , FIN_PRODUCT_TYPE.TYPE_12 from fin_product left join FIN_PRODUCT_ADD on fin_product.FINPROD_ID=FIN_PRODUCT_ADD.FINPROD_ID left join FIN_PRODUCT_TYPE on fin_product.FINPROD_ID=FIN_PRODUCT_TYPE.FINPROD_ID where 1=1
and fin_product.FINPROD_ID in
#{item}
union all select FIN_TRADE_PRODUCT.FINPROD_ID FINPROD_IDZ, FIN_TRADE_PRODUCT_ADD.FINPROD_ID FINPROD_IDFS , FIN_TRADE_PRODUCT.FINPROD_ID FINPROD_IDJY , FIN_PRODUCT_TYPE.TYPE_3 , FIN_TRADE_PRODUCT.BRANCH BRANCHJY , FIN_TRADE_PRODUCT.FINPROD_TYPE , FIN_TRADE_PRODUCT.FINPROD_TYPE2 , null , null , FIN_TRADE_PRODUCT.PROFIT_TYPE , FIN_TRADE_PRODUCT.BRANCH_TYPE , FIN_TRADE_PRODUCT.CHL_AGRT_ID , FIN_TRADE_PRODUCT.PRIN , FIN_TRADE_PRODUCT.CCY , FIN_TRADE_PRODUCT.VDATE , FIN_TRADE_PRODUCT.MDATE , FIN_TRADE_PRODUCT.TERM , FIN_TRADE_PRODUCT.INT_TYPE , FIN_TRADE_PRODUCT.INT_RATE , FIN_TRADE_PRODUCT.INT_RATE_ID , FIN_TRADE_PRODUCT.BASIS , FIN_TRADE_PRODUCT.M_PRIN_AMT , FIN_TRADE_PRODUCT.M_INT_AMT , FIN_TRADE_PRODUCT.M_TRADE_AMT , FIN_TRADE_PRODUCT.CAPI_INCOME_FEATURE , FIN_TRADE_PRODUCT.O_FINPROD_ID , FIN_TRADE_PRODUCT.TRADE_MARKET , FIN_TRADE_PRODUCT.CALENDAR_ID , FIN_TRADE_PRODUCT.TERM_TYPE , FIN_TRADE_PRODUCT.COUNTER_ID , FIN_TRADE_PRODUCT.M_UNIT_CPRICE , FIN_TRADE_PRODUCT.M_UNIT_INT , FIN_TRADE_PRODUCT.M_UNIT_FPRICE , FIN_TRADE_PRODUCT.M_YIELD , FIN_TRADE_PRODUCT.M_DELIVERY_TYPE , FIN_TRADE_PRODUCT.VPAY_DATE , FIN_TRADE_PRODUCT.MPAY_DATE , FIN_TRADE_PRODUCT.CONTRACT_NO , FIN_TRADE_PRODUCT.ACT_CAP_DAYS , FIN_TRADE_PRODUCT.IRS_TYPE , FIN_TRADE_PRODUCT.EXC_PS , FIN_TRADE_PRODUCT.CUR_PAIR , FIN_TRADE_PRODUCT.EXC_FXS_TERM_TYPE , FIN_TRADE_PRODUCT.USD_AMT , FIN_TRADE_PRODUCT.DIF_SETTLE_REF_RATE , FIN_TRADE_PRODUCT.CONFLICT_SOLVE_WAY , FIN_TRADE_PRODUCT.PERIOD_ID , FIN_TRADE_PRODUCT.IS_RUSH_BACK , FIN_TRADE_PRODUCT.CONTRACT_NAME , null , FIN_TRADE_PRODUCT_ADD.REGIST_ORG, FIN_TRADE_PRODUCT_ADD.PLEDGE_SEC_NUM , FIN_TRADE_PRODUCT.CREATE_USER , FIN_TRADE_PRODUCT.CREATE_DEPT , FIN_TRADE_PRODUCT.CREATE_TIME , FIN_TRADE_PRODUCT.UPDATE_USER , FIN_TRADE_PRODUCT.UPDATE_TIME , FIN_TRADE_PRODUCT_ADD.EXCHANGE_PLEDGE , FIN_TRADE_PRODUCT_ADD.SUPPLY_CLAUSE, FIN_TRADE_PRODUCT_ADD.IS_ACCR_PENALTY_INT, FIN_TRADE_PRODUCT_ADD.PENALTY_BASE_TYPE, FIN_TRADE_PRODUCT_ADD.OPT_FEE_PAY_TYPE, FIN_TRADE_PRODUCT_ADD.OPT_FEE_AMT, FIN_TRADE_PRODUCT_ADD.OPT_FEE_RATE, null , null , null , null , null , repFee.amt issueAmt , /*回购费用计入成本，计提用*/ null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , null , /*null ,*/ null , FIN_PRODUCT_TYPE.TYPE_1 , FIN_PRODUCT_TYPE.TYPE_2 , FIN_PRODUCT_TYPE.TYPE_4 , FIN_PRODUCT_TYPE.TYPE_5 , FIN_PRODUCT_TYPE.TYPE_6 , FIN_PRODUCT_TYPE.TYPE_7 , FIN_PRODUCT_TYPE.TYPE_8 , FIN_PRODUCT_TYPE.TYPE_9 , FIN_PRODUCT_TYPE.TYPE_10 , FIN_PRODUCT_TYPE.TYPE_11 , FIN_PRODUCT_TYPE.TYPE_12 from FIN_TRADE_PRODUCT left join FIN_TRADE_PRODUCT_ADD on FIN_TRADE_PRODUCT.FINPROD_ID=FIN_TRADE_PRODUCT_ADD.FINPROD_ID left join FIN_PRODUCT_TYPE on FIN_TRADE_PRODUCT.FINPROD_ID=FIN_PRODUCT_TYPE.FINPROD_ID left join (select TRD_TRADE_FEE_DETAIL.trade_id FINPROD_ID,sum(TRD_TRADE_FEE_DETAIL.fee_amt)amt from TRD_TRADE_FEE_DETAIL inner join FIN_TRADE_PRODUCT on FIN_TRADE_PRODUCT.FINPROD_ID=TRD_TRADE_FEE_DETAIL.trade_id where 1=1
and FIN_TRADE_PRODUCT.FINPROD_ID in
#{item}
and FIN_TRADE_PRODUCT.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F02},#{FINPROD_TYPE_TG_F03},#{FINPROD_TYPE_TG_F04},#{FINPROD_TYPE_TG_F05}) and trade_id is not null group by TRD_TRADE_FEE_DETAIL.trade_id)repFee on FIN_TRADE_PRODUCT.FINPROD_ID=repFee.FINPROD_ID where 1=1
and FIN_TRADE_PRODUCT.FINPROD_ID in
#{item}
and FIN_TRADE_PRODUCT.BRANCH = 0
